    fn crafted_site() -> (SiteId, SiteState) {
        (
            SiteId::from("pad"),
            SiteState {
                id: SiteId::from("pad"),
                inventory: BTreeMap::new(),
            },
        )
    }

    fn crafted_fatals(
        orbits: PatchedConics,
        physics: Option<PhysicsConfig>,
        s: WorldSnapshot,
    ) -> bool {
        matches!(World::restore(orbits, physics, s), Err(SimError::Fatal(_)))
    }

    /// The vessel payload gates: the OnRails orbit proves against the
    /// handed-in model, every serialized craft passes the spawn gate
    /// in every residence, quaternions carry nonzero norm, and the
    /// next-id checks are overflow-safe.
    #[test]
    fn restore_rejects_crafted_vessel_payloads() {
        let good = || World::new().snapshot().unwrap();
        let with_vessel = |mut s: WorldSnapshot, v: Vessel| {
            s.vessels.insert(v.id, v);
            s.next_vessel_id = s.vessels.keys().next_back().map_or(0, |id| id.0 + 1);
            s
        };

        // A plain OnRails vessel restores fine against the model that
        // produced it — but refuses an empty model (the `parent` gate).
        let s = with_vessel(
            good(),
            crafted_rails_vessel(VesselId(0), leo_elements(), None),
        );
        World::restore(test_system(), None, s.clone()).unwrap();
        assert!(crafted_fatals(PatchedConics::new(BTreeMap::new()), None, s));

        // A non-finite element fails `state_at`'s funnel even with the
        // parent resolved; so does a NaN `period_s` (unhashed but
        // still crafted input).
        let mut bad_el = leo_elements();
        bad_el.semi_major_axis_m = f64::NAN;
        let s = with_vessel(good(), crafted_rails_vessel(VesselId(0), bad_el, None));
        assert!(crafted_fatals(test_system(), None, s));
        let mut bad_el = leo_elements();
        bad_el.period_s = f64::NAN;
        let s = with_vessel(good(), crafted_rails_vessel(VesselId(0), bad_el, None));
        assert!(crafted_fatals(test_system(), None, s));

        // A serialized craft must pass the spawn/manufacture gate in
        // every residence — NaN part mass is refused on rails too.
        let mut bad_craft = box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0);
        bad_craft.parts[0].mass_kg = f64::NAN;
        let mut v = crafted_rails_vessel(VesselId(0), leo_elements(), Some(bad_craft));
        v.thermal
            .part_temps_k
            .insert(csp_phys::PartNodeId(0), 300.0);
        let s = with_vessel(good(), v);
        assert!(crafted_fatals(test_system(), None, s));

        // A valid InBubble vessel restores; a zero-norm rot is refused
        // (finite but un-normalizable — the `SetAttitude` rule).
        let craft = box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0);
        let body = csp_phys::weld(&craft.graph, &craft.parts).unwrap();
        let mut v = crafted_rails_vessel(VesselId(0), leo_elements(), Some(craft));
        v.state = VesselState::InBubble(body);
        v.thermal
            .part_temps_k
            .insert(csp_phys::PartNodeId(0), 300.0);
        let s = with_vessel(good(), v);
        World::restore(test_system(), crafted_physics(), s.clone()).unwrap();
        let mut s2 = s.clone();
        if let VesselState::InBubble(b) = &mut s2.vessels.get_mut(&VesselId(0)).unwrap().state {
            b.rot = DQuat::new(0.0, 0.0, 0.0, 0.0);
        }
        assert!(crafted_fatals(test_system(), crafted_physics(), s2));

        // A valid SurfaceLatched vessel restores; a zero-norm
        // orientation or a pose on the wrong body is refused.
        let craft = box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0);
        let mut v = crafted_rails_vessel(VesselId(0), leo_elements(), Some(craft));
        v.state = VesselState::SurfaceLatched(SurfacePose {
            body: BodyId::from("p"),
            latitude_rad: 0.0,
            longitude_rad: 0.0,
            altitude_m: 0.0,
            orientation: DQuat::IDENTITY,
        });
        v.thermal
            .part_temps_k
            .insert(csp_phys::PartNodeId(0), 300.0);
        let s = with_vessel(good(), v);
        World::restore(test_system(), crafted_physics(), s.clone()).unwrap();
        let mut s2 = s.clone();
        if let VesselState::SurfaceLatched(p) = &mut s2.vessels.get_mut(&VesselId(0)).unwrap().state
        {
            p.orientation = DQuat::new(0.0, 0.0, 0.0, 0.0);
        }
        assert!(crafted_fatals(test_system(), crafted_physics(), s2));
        let mut s2 = s;
        if let VesselState::SurfaceLatched(p) = &mut s2.vessels.get_mut(&VesselId(0)).unwrap().state
        {
            p.body = BodyId::from("m");
        }
        assert!(crafted_fatals(test_system(), crafted_physics(), s2));

        // A `u64::MAX` live id must `Fatal`, never overflow the
        // next-id check (the `id.0 + 1` class).
        let mut s = good();
        s.vessels.insert(
            VesselId(u64::MAX),
            crafted_rails_vessel(VesselId(u64::MAX), leo_elements(), None),
        );
        s.next_vessel_id = 0;
        assert!(crafted_fatals(test_system(), None, s));
    }

    /// The arena payload gates: build crafts and sites, colony floats
    /// and the inspection pairing, roster/site/bench/instance arenas,
    /// autopilot bindings, the script budget, and in-flight crew.
    #[test]
    #[allow(clippy::too_many_lines)] // one section per gate, kept together
    fn restore_rejects_crafted_snapshot_arenas() {
        let good = || World::new().snapshot().unwrap();
        let inspection_event = |seq| ScheduledEvent {
            tick: 10,
            seq,
            class: EventClass::Silent,
            kind: EventKind::ColonyInspection {
                colony: ColonyId(0),
            },
        };

        // ActiveBuild: an unknown site or a malformed craft is refused;
        // the paired event otherwise matches.
        let mut s = good();
        s.economy.sites.insert(crafted_site().0, crafted_site().1);
        s.builds.insert(
            manufacture::BuildId(0),
            manufacture::ActiveBuild {
                id: manufacture::BuildId(0),
                site: SiteId::from("pad"),
                craft: box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0),
                complete_tick: 10,
            },
        );
        s.next_build_id = 1;
        s.event_heap = vec![ScheduledEvent {
            tick: 10,
            seq: 0,
            class: events::class_of(
                &EventKind::ConstructionComplete {
                    build: manufacture::BuildId(0),
                },
                &BTreeSet::new(),
            ),
            kind: EventKind::ConstructionComplete {
                build: manufacture::BuildId(0),
            },
        }];
        s.next_event_seq = 1;
        World::restore(test_system(), None, s.clone()).unwrap();
        let mut s2 = s.clone();
        s2.builds
            .get_mut(&manufacture::BuildId(0))
            .unwrap()
            .craft
            .parts[0]
            .mass_kg = f64::NAN;
        assert!(crafted_fatals(test_system(), None, s2));
        let mut s2 = s;
        s2.economy.sites.clear();
        assert!(crafted_fatals(test_system(), None, s2));

        // Colony gates: unresolved site/body refs, non-finite pose and
        // solve floats, incoherent module defs, a solve stamped ahead
        // of the clock, and fractions parallel to modules.
        let mut s = good();
        s.economy.sites.insert(crafted_site().0, crafted_site().1);
        s.colonies.insert(ColonyId(0), crafted_colony(ColonyId(0)));
        s.next_colony_id = 1;
        World::restore(test_system(), None, s.clone()).unwrap();
        for bad in [
            |c: &mut Colony| c.latitude_rad = f64::NAN,
            |c: &mut Colony| c.site = SiteId::from("nowhere"),
            |c: &mut Colony| c.body = BodyId::from("nowhere"),
            |c: &mut Colony| c.t_eq_k = Some(f64::NAN),
            |c: &mut Colony| c.module_fractions = vec![2.0],
            |c: &mut Colony| {
                c.modules.push(colonies::ColonyModule {
                    def: csp_data::ColonyModuleDef::Battery { capacity: -1.0 },
                    damaged: false,
                })
            },
            |c: &mut Colony| c.solved_tick = u64::MAX,
            |c: &mut Colony| c.module_fractions = vec![0.5],
        ] {
            let mut s2 = s.clone();
            bad(s2.colonies.get_mut(&ColonyId(0)).unwrap());
            assert!(crafted_fatals(test_system(), None, s2));
        }

        // The inspection pairing — a live colony's `Some(t)` requires
        // exactly one pending event at t; the record-less event and
        // the event-less record are both refused.
        let mut s2 = s.clone();
        s2.colonies.get_mut(&ColonyId(0)).unwrap().inspection_tick = Some(10);
        s2.event_heap = vec![inspection_event(0)];
        s2.next_event_seq = 1;
        World::restore(test_system(), None, s2.clone()).unwrap();
        let mut s3 = s2.clone();
        s3.event_heap = Vec::new();
        assert!(crafted_fatals(test_system(), None, s3));
        let mut s3 = s2.clone();
        s3.colonies.get_mut(&ColonyId(0)).unwrap().inspection_tick = Some(11);
        assert!(crafted_fatals(test_system(), None, s3));
        let mut s3 = s2;
        s3.colonies.get_mut(&ColonyId(0)).unwrap().inspection_tick = None;
        assert!(crafted_fatals(test_system(), None, s3));
        // A dormant colony keeps the record but holds no events — the
        // terminal states' carve-out.
        let mut s3 = s.clone();
        {
            let c = s3.colonies.get_mut(&ColonyId(0)).unwrap();
            c.state = ColonyState::Dormant;
            c.inspection_tick = Some(10);
        }
        World::restore(test_system(), None, s3.clone()).unwrap();
        s3.event_heap = vec![inspection_event(0)];
        s3.next_event_seq = 1;
        assert!(crafted_fatals(test_system(), None, s3));

        // The roster's own keys sit below `next_crew_id`, like seats.
        let mut s = good();
        s.economy.crew.insert(
            CrewId(5),
            CrewMember {
                name: "x".into(),
                kind: CrewKind::Pilot,
                skill: 1,
                location: CrewLocation::Unassigned,
                salary_per_s: 0.0,
                status: CrewStatus::Active,
            },
        );
        s.next_crew_id = 5;
        assert!(crafted_fatals(test_system(), None, s));

        // `SiteState.id` must equal its arena key — the hash reads the
        // inline id.
        let mut s = good();
        s.economy.sites.insert(
            SiteId::from("pad"),
            SiteState {
                id: SiteId::from("other"),
                inventory: BTreeMap::new(),
            },
        );
        assert!(crafted_fatals(test_system(), None, s));

        // An autopilot bound to a missing vessel.
        let mut s = good();
        s.autopilots.insert(
            VesselId(9),
            AutopilotState {
                program: AutopilotProgram::Ascent {
                    target_apoapsis_m: 100_000.0,
                    target_periapsis_m: 100_000.0,
                },
                enabled: true,
                persist: PersistMap::default(),
            },
        );
        assert!(crafted_fatals(test_system(), None, s));

        // A zero script op budget — the `event_budget` rule.
        let mut s = good();
        s.script_op_budget = 0;
        assert!(crafted_fatals(test_system(), None, s));

        // Two in-flight transfers carrying the same crew member.
        let mut s = good();
        for (id, tick) in [(TransferId(0), 10), (TransferId(1), 11)] {
            s.transfers.insert(
                id,
                ActiveTransfer {
                    id,
                    from: transfers::TransferEnd::Vessel(VesselId(0)),
                    to: transfers::TransferEnd::Vessel(VesselId(1)),
                    cargo: TransferCargo::Crew { crew: CrewId(0) },
                    complete_tick: tick,
                },
            );
        }
        s.next_transfer_id = 2;
        s.next_vessel_id = 2;
        s.next_crew_id = 1;
        s.event_heap = vec![
            ScheduledEvent {
                tick: 10,
                seq: 0,
                class: EventClass::Clamping,
                kind: EventKind::TransferComplete {
                    transfer: TransferId(0),
                },
            },
            ScheduledEvent {
                tick: 11,
                seq: 1,
                class: EventClass::Clamping,
                kind: EventKind::TransferComplete {
                    transfer: TransferId(1),
                },
            },
        ];
        s.next_event_seq = 2;
        assert!(crafted_fatals(test_system(), None, s));

        // A bench run on an unknown site.
        let mut s = good();
        s.bench_runs.insert(
            reliability::BenchId(0),
            reliability::ActiveBench {
                id: reliability::BenchId(0),
                site: SiteId::from("nowhere"),
                family: csp_data::FamilyId::from("f"),
                units: 1.0,
                complete_tick: 10,
            },
        );
        s.next_bench_id = 1;
        s.event_heap = vec![ScheduledEvent {
            tick: 10,
            seq: 0,
            class: EventClass::Silent,
            kind: EventKind::BenchTestComplete {
                run: reliability::BenchId(0),
            },
        }];
        s.next_event_seq = 1;
        assert!(crafted_fatals(test_system(), None, s));

        // Two vessels sharing one part-instance id — the KDF keys
        // `instance.0` alone, so uniqueness is save-global.
        let mut s = good();
        for vid in [VesselId(0), VesselId(1)] {
            let craft = box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0);
            let mut v = crafted_rails_vessel(vid, leo_elements(), Some(craft));
            v.thermal
                .part_temps_k
                .insert(csp_phys::PartNodeId(0), 300.0);
            v.reliability.insert(
                csp_phys::PartNodeId(0),
                reliability::fresh_record(0, PartInstanceId(0), 0),
            );
            s.vessels.insert(vid, v);
        }
        s.next_vessel_id = 2;
        s.next_part_instance_id = 1;
        assert!(crafted_fatals(test_system(), None, s));
    }

    /// F2: the publish horizon is physical — `SOI_SCAN_HORIZON_PERIODS`
    /// periods of the tightest orbit — and the per-publish sample spend
    /// stays pinned far below the cap for the LEO and hyperbolic
    /// fixtures (not sized *by* the cap).
    #[test]
    fn publish_spend_is_physical_and_bounded() {
        let model = test_system();
        let leo = OrbitState {
            parent: BodyId::from("p"),
            elements: leo_elements(),
            epoch: SimTime::from_ticks(0),
        };
        let span = model.scan_horizon(&leo).unwrap().unwrap();
        // LEO's own period is the tightest orbit in play.
        let t_leo_s =
            2.0 * core::f64::consts::PI / libm::sqrt(MU_TERRIN / (6.75e5 * 6.75e5 * 6.75e5));
        assert_eq!(span, (4.0 * t_leo_s * csp_core::TICK_HZ as f64) as u64);
        let (ev, samples) = model
            .next_soi_event_within(
                &leo,
                SimTime::from_ticks(0),
                SimTime::from_ticks(span),
                orbit::SOI_SCAN_MAX_SAMPLES,
                None,
                None,
            )
            .unwrap();
        assert!(ev.is_none());
        // Spend = Σ_c (1 + ⌈span/h_c⌉) — pinned through the overlay's
        // own strides; the whole publish costs ~10² samples, not ~10⁶.
        let bound: u64 = model
            .scan_strides(&leo)
            .unwrap()
            .iter()
            .map(|s| 1 + span.div_ceil(s.stride_ticks))
            .sum();
        assert_eq!(samples, bound);
        assert!(samples < orbit::SOI_SCAN_MAX_SAMPLES / 1000);

        // The hyperbolic fixture: the tightest orbit is the moon's, and
        // one publish covers the whole encounter chain.
        let model = test_system_crossing();
        let hyp = OrbitState {
            parent: BodyId::from("p"),
            elements: crossing_vessel_elements(),
            epoch: SimTime::from_ticks(0),
        };
        let span = model.scan_horizon(&hyp).unwrap().unwrap();
        let t_moon_s =
            2.0 * core::f64::consts::PI / libm::sqrt(MU_TERRIN / (1.2e7 * 1.2e7 * 1.2e7));
        assert_eq!(span, (4.0 * t_moon_s * csp_core::TICK_HZ as f64) as u64);
        let (ev, samples) = model
            .next_soi_event_within(
                &hyp,
                SimTime::from_ticks(0),
                SimTime::from_ticks(span),
                orbit::SOI_SCAN_MAX_SAMPLES,
                None,
                None,
            )
            .unwrap();
        assert!(matches!(ev, Some(ref e) if e.body == BodyId::from("m")
            && e.direction == orbit::SoiDirection::Enter));
        assert!(samples < orbit::SOI_SCAN_MAX_SAMPLES / 4);
    }

    // ==================== M2-C: the physics bubble ====================
    //
    // Terrin's §3.0 numbers as an `Environment` literal (the fixture the
    // physics tests share): the spinning datum (21 600 s day), the 70 km
    // atmosphere, and the §2.9 default solver/settle tunables.
    fn test_env(spin: bool) -> csp_phys::Environment {
        csp_phys::Environment {
            body_center: DVec3::ZERO,
            radius_m: 600_000.0,
            mu_m3_per_s2: 3.5316e12,
            body_spin: if spin {
                DVec3::new(0.0, 0.0, 2.0 * core::f64::consts::PI / 21_600.0)
            } else {
                DVec3::ZERO
            },
            atmosphere: Some(csp_data::AtmosphereDef {
                sea_level_pressure_pa: 101_325.0,
                scale_height_m: 5_600.0,
                top_m: 70_000.0,
                molar_mass_kg_per_mol: 0.028_97,
                heat_capacity_ratio: 1.40,
                temperature_knots: vec![
                    csp_data::TemperatureKnot {
                        altitude_m: 0.0,
                        temperature_k: 288.15,
                    },
                    csp_data::TemperatureKnot {
                        altitude_m: 70_000.0,
                        temperature_k: 200.15,
                    },
                ],
            }),
            settle_v: 0.05,
            settle_w: 0.05,
            settle_ticks: 128,
            friction_mu: 0.5,
            drag_cd: 1.0,
            // Bare-sphere ground — the suite's landing/impact fixtures
            // are authored against the datum, not a seeded field.
            terrain: None,
        }
    }

    /// A one-part box craft — a `mass_kg` box with an engine on its −z
    /// face thrusting along +z (no engine when `thrust_n` is 0).
    fn box_craft(mass_kg: f64, half: DVec3, thrust_n: f64) -> CraftDef {
        let mut graph = csp_phys::PartGraph::new(csp_phys::PartNodeId(0));
        graph.nodes.insert(
            csp_phys::PartNodeId(0),
            csp_phys::PartNode::new(None, csp_phys::PartTransform::IDENTITY, 0),
        );
        CraftDef {
            hash_memo: Default::default(),
            part_ids: vec![],
            graph,
            part_costs: vec![0.0],
            parts: vec![csp_phys::WeldPart {
                experiments: Vec::new(),
                lab: None,
                engine: None,
                parachute: None,
                dock_ports: vec![],
                tanks: vec![],
                crew_seats: 0,
                structural: csp_data::StructuralDef::unlimited(),
                mass_kg,
                com: DVec3::ZERO,
                inertia: csp_phys::SymMat3::solid_box(mass_kg, half),
                collider: csp_phys::ColliderShape::Box { half_extents: half },
                force_sites: if thrust_n > 0.0 {
                    vec![csp_phys::ForceSite::new(
                        DVec3::new(0.0, 0.0, -half.z),
                        DVec3::Z,
                        csp_phys::ForceSiteKind::Thrust,
                        thrust_n,
                    )]
                } else {
                    Vec::new()
                },
                aero: csp_data::AeroDef::constant(1.0, 0.0, 1.0),
                thermal: csp_data::ThermalDef {
                    heat_capacity_j_per_k: 400_000.0,
                    max_temp_k: 1_100.0,
                    emissivity: 0.8,
                    conduction_w_per_k: 60.0,
                },
            }],
            reliability: vec![],
        }
    }

    fn physics_world(spin: bool) -> World {
        World::with_physics(
            test_system(),
            PhysicsConfig {
                environment: test_env(spin),
                dominant: BodyId::from("p"),
                bubble_radius_m: DEFAULT_BUBBLE_RADIUS_M,
            },
            DEFAULT_MAX_EVENTS_PER_FRAME,
        )
    }

    /// Spawn `craft` — drains at tick 0; asserts the vessel is resident.
    /// A clearing conic auto-rails at the first stepped tick (the new
    /// bubble→rails edge), so `OnRails` counts as resident here.
    fn spawn_physical(w: &mut World, cmd: SimCommand) {
        w.enqueue(SourceClass::Ui, 0, cmd);
        w.step_frame(1).unwrap();
        assert!(matches!(
            w.vessels()[&VesselId(0)].state,
            VesselState::InBubble(_) | VesselState::OnRails(_)
        ));
    }

    /// A spawn velocity that keeps a 200 km resident `InBubble` —
    /// the auto bubble→rails conversion would rail a coasting
    /// *clearing* conic at the first stepped tick, so fixtures that
    /// exercise in-bubble physics ride a 0.6-circular dipping conic
    /// (periapsis below the surface/atmosphere floor: a suborbital
    /// hop IS a bubble flight). The vessel coasts near apoapsis for
    /// tens of thousands of ticks — longer than any fixture runs.
    fn in_bubble_vel(r: f64) -> DVec3 {
        DVec3::new(0.0, 0.6 * libm::sqrt(3.5316e12 / r), 0.0)
    }

    /// Enqueue a `SpawnPhysicalVessel` for a ballistic resident 200 km
    /// over Terrin — above `top_m`, on the 0.6-circular dipping conic:
    /// the auto bubble→rails edge never takes it (periapsis below the
    /// surface), so it ticks per-tick physics for tens of thousands of
    /// ticks — long enough for the script/lease/rollback fixtures that
    /// need an honest `InBubble` vessel — before the descent finally
    /// impacts the surface and the resident is removed, identically in
    /// every partition. The spawn drains at the caller's next tick
    /// boundary.
    fn enqueue_orbiter(w: &mut World) {
        let hi = DVec3::new(TERRIN_R + 200_000.0, 0.0, 0.0);
        w.enqueue(
            SourceClass::Ui,
            0,
            SimCommand::SpawnPhysicalVessel {
                craft: box_craft(1_000.0, DVec3::new(0.5, 0.5, 0.5), 0.0),
                pos: hi,
                rot: csp_core::DQuat::IDENTITY,
                vel: in_bubble_vel(hi.norm()),
                ang_vel: DVec3::ZERO,
            },
        );
    }

    const TERRIN_R: f64 = 600_000.0;
    /// The surface co-rotation velocity at `p` — `ω × (p − center)`.
    fn surface_vel(p: DVec3, env: &csp_phys::Environment) -> DVec3 {
        env.body_spin.cross(p - env.body_center)
    }
    /// Body +z → world +x (up at the +x pad site).
    fn pad_rot() -> csp_core::DQuat {
        csp_core::DQuat::from_axis_angle(DVec3::Y, core::f64::consts::FRAC_PI_2)
    }

    /// The `test_env` mock is bound field-wise to Terrin's authored
    /// `body.ron` via `Environment::for_body` — the real construction
    /// path — so a RON edit reds here instead of leaving the fixture
    /// silently stale. One documented carve-out: `temperature_knots`.
    /// The mock carries the authored table's two ENDPOINTS only
    /// (0 m → 288.15 K, 70 km → 200.15 K) — a straight ramp that
    /// drops the authored stratosphere bump (216.65 K at 12 km,
    /// 250.35 K at 40 km). The delta is load-bearing, not sloppiness:
    /// the suite pins the mock's warmer ambient —
    /// `explosion_and_overheat_same_tick_destroys_part` relies on
    /// ~276 K at 10 km to push its 250 K `max_temp_k` leaf over limit
    /// on the first `thermal_step` (authored: ~229 K — the leaf would
    /// not overheat). Endpoint edits in the RON must red this test;
    /// mid-table edits are exactly the carve-out.
    #[test]
    fn test_env_binds_to_authored_terrin_except_temp_knots() {
        let defs = authored_home_defs();
        let terrin = defs
            .iter()
            .find(|b| b.id == BodyId::from("terrin"))
            .unwrap();
        let authored = csp_phys::Environment::for_body(terrin, DVec3::ZERO, Some(21_600.0));
        let mock = test_env(true);
        assert_eq!(mock.body_center, authored.body_center);
        assert_eq!(mock.radius_m, authored.radius_m);
        assert_eq!(mock.mu_m3_per_s2, authored.mu_m3_per_s2);
        assert_eq!(mock.body_spin, authored.body_spin);
        assert_eq!(mock.settle_v, authored.settle_v);
        assert_eq!(mock.settle_w, authored.settle_w);
        assert_eq!(mock.settle_ticks, authored.settle_ticks);
        assert_eq!(mock.friction_mu, authored.friction_mu);
        assert_eq!(mock.drag_cd, authored.drag_cd);
        let (m_atm, a_atm) = (
            mock.atmosphere.as_ref().unwrap(),
            authored.atmosphere.as_ref().unwrap(),
        );
        assert_eq!(m_atm.sea_level_pressure_pa, a_atm.sea_level_pressure_pa);
        assert_eq!(m_atm.scale_height_m, a_atm.scale_height_m);
        assert_eq!(m_atm.top_m, a_atm.top_m);
        assert_eq!(m_atm.molar_mass_kg_per_mol, a_atm.molar_mass_kg_per_mol);
        assert_eq!(m_atm.heat_capacity_ratio, a_atm.heat_capacity_ratio);
        // The carve-out, pinned exactly: the mock's table is the
        // authored endpoints, and it must stay a strict subset.
        assert!(
            a_atm.temperature_knots.len() > m_atm.temperature_knots.len(),
            "the carve-out assumes the authored table is richer"
        );
        assert_eq!(m_atm.temperature_knots.len(), 2);
        assert_eq!(
            m_atm.temperature_knots[0],
            *a_atm.temperature_knots.first().unwrap()
        );
        assert_eq!(
            m_atm.temperature_knots[1],
            *a_atm.temperature_knots.last().unwrap()
        );
    }

    /// §2.4: a physical spawn welds its craft into a bubble-resident
    /// `WeldedBody`; gravity alone pulls it down at ~g.
    #[test]
    fn physical_spawn_welds_and_falls() {
        let mut w = physics_world(false);
        let pos = DVec3::new(TERRIN_R + 100.0, 0.0, 0.0);
        spawn_physical(
            &mut w,
            SimCommand::SpawnPhysicalVessel {
                craft: box_craft(5_000.0, DVec3::new(0.5, 0.5, 1.5), 0.0),
                pos,
                rot: pad_rot(),
                vel: DVec3::ZERO,
                ang_vel: DVec3::ZERO,
            },
        );
        let v = &w.vessels()[&VesselId(0)];
        assert_eq!(v.craft.as_ref().unwrap().parts.len(), 1);
        let body = v.body().unwrap();
        // The spawn drained at tick 0; the body then ticked once —
        // ~2.4 mm of fall (g·dt²/2 ≈ 9.81/4096) already accrued.
        assert!((body.pos.x - pos.x).abs() < 0.01);
        assert_eq!(body.pos.y, 0.0);
        assert_eq!(body.mass_kg, 5_000.0);
        // 65 ticks ≈ 1.016 s of free fall: v ≈ −9.96·x̂, drop ≈ 5.1 m.
        w.step_frame(65).unwrap();
        let body = w.vessels()[&VesselId(0)].body().unwrap();
        assert!((body.vel.x + 9.96).abs() < 0.02);
        assert!((body.pos.x - (pos.x - 5.1)).abs() < 0.2);
    }

    /// A two-node craft: payload box (root, node 1) + a big thin
